uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;

// User Parameters (Preserved)
uniform float u_speed;
uniform float u_fov;
uniform float u_camera_dist;
uniform float u_glow_intensity;
uniform float u_complexity; 
uniform float u_viscosity;
uniform float u_paper_texture;
uniform float u_metallic_shine;
uniform float u_bloom_brightness;
uniform float u_paint_thickness;
uniform float u_creaminess;
uniform float u_melting;
uniform float u_berry_intensity; 
uniform float u_wave_height;
uniform float u_hole_size;
uniform float u_vortex_strength;
uniform float u_blue_shift;
uniform float u_bubblegum_pop;
uniform float u_drift_cycle;

// New Parameter for background intensity control
uniform float u_background_blue;

out vec4 fragColor;

// --- UTILS ---
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float noise(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Multi-tone Palette updated for "Bubblegum & Light Blue"
vec3 getIceCreamPalette(float t, float mask) {
    // Light Blue (Baby blue / Electric sky)
    vec3 lightBlue    = vec3(0.5, 0.8, 1.0) * u_berry_intensity; 
    // Bubblegum Pink (Soft, vibrant pink)
    vec3 bubblePink   = vec3(1.0, 0.5, 0.85) * u_berry_intensity; 
    // Cream (White base)
    vec3 iceCream     = vec3(1.0, 0.98, 1.0); 

    // Deeper shade for depth (Soft Lavender or Deep Sky Blue)
    vec3 depthColor   = mix(vec3(0.4, 0.2, 0.6), vec3(0.0, 0.4, 0.7), u_blue_shift);

    float selector = sin(t * 1.5 + mask * 4.0) * 0.5 + 0.5;

    // Mix between Pink and Blue based on the spatial flow and the "pop" factor
    vec3 finalCol = mix(lightBlue, bubblePink, smoothstep(0.2, 0.8, selector + (u_bubblegum_pop - 0.5)));

    // Swirl in the creamy white
    finalCol = mix(finalCol, iceCream, smoothstep(0.7, 0.99, selector) * u_creaminess);

    // Inject shadow depth
    finalCol = mix(finalCol, depthColor, (1.0 - selector) * 0.3);

    return finalCol;
}

void main() {
    // 1. Coordinate Setup
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv_orig = uv;

    // Zoom control
    uv *= (3.0 - u_fov); 

    // Direction Logic: Calculate a slow cosine-based multiplier that oscillates between 1.0 and -1.0
    float dirMultiplier = cos(iTime * (3.14159 / u_drift_cycle));

    float t = iTime * u_speed * 0.15;
    float r = length(uv);

    // 2. Liquid Distortion & Vortex Folding
    float vortex = (u_vortex_strength * dirMultiplier) / (r + 0.1);
    uv *= rot(vortex + t * 0.5 * dirMultiplier);

    // Suck the UVs into the hole (Inverse distance)
    float pull = pow(clamp(1.0 - r, 0.0, 1.0), 2.0) * 0.5;
    vec2 p = uv * (1.0 + pull);

    float flow = 0.0;

    // Melt effect: Slight downward drag + radial inward flow
    p.y -= t * u_melting * 0.25 * dirMultiplier;

    // Wave influence for fractal folding
    float waveAmp = u_wave_height;

    for(float i = 1.0; i <= u_complexity; i++) {
        p.x += (waveAmp / i) * sin(i * 1.8 * p.y + (t * dirMultiplier) + u_viscosity * 4.0);
        p.y += (waveAmp / i) * cos(i * 1.8 * p.x + (t * dirMultiplier) + u_viscosity * 4.0);
        p *= rot(u_camera_dist * 0.04 * dirMultiplier);
        flow += length(p - uv);
    }

    // 3. Distance Fields for the Creamy folds + Center Hole
    float d = length(sin(p * 0.9)) - 0.45;

    // Create the hole mask
    float hole = smoothstep(u_hole_size, u_hole_size + 0.1, r);
    // Depth intensity based on distance from center
    float holeDepth = smoothstep(u_hole_size - 0.1, u_hole_size + 0.5, r);

    // Soft blend for "Thick" feel
    float mask = smoothstep(1.0 + u_paint_thickness * 0.5, -0.3, d) * hole;

    // Add internal depth glow
    float glow = exp(-abs(d) * 4.0) * u_glow_intensity * hole;

    // 4. Color Compositing
    vec3 baseCol = getIceCreamPalette(flow * 0.12 + t * 0.15 * dirMultiplier, mask);

    // Modified: Instead of black, we use a light baby blue for the deep/void areas
    vec3 bgCol = vec3(0.6, 0.85, 1.0) * u_background_blue; 

    // Apply depth darkening to the base colors as they approach the center
    baseCol = mix(bgCol, baseCol, holeDepth);

    // Mix the fluid onto the background
    vec3 finalCol = mix(bgCol, baseCol, clamp(mask + glow, 0.0, 1.0));

    // 5. Glossy Reflections
    vec3 n = normalize(vec3(dFdx(flow), dFdy(flow), 0.2 / (0.1 + u_wave_height))); 
    vec3 lightDir = normalize(vec3(sin(t * 0.3 * dirMultiplier), 1.0, 1.5));
    float spec = pow(max(0.0, dot(n, lightDir)), 12.0) * u_metallic_shine * hole;

    // Highlights
    vec3 highlight = mix(baseCol, vec3(1.0, 1.0, 1.0), 0.8);
    finalCol += spec * highlight * u_bloom_brightness;

    // 6. Surface Texture (Sprinkles/Seeds)
    float grain = noise(gl_FragCoord.xy * 0.4);
    if (u_paper_texture > 0.0) {
        float seedPattern = step(0.985, noise(p * 20.0 + flow));
        vec3 sprinkleCol = mix(vec3(1.0, 0.0, 0.5), vec3(0.0, 1.0, 1.0), sin(flow * dirMultiplier));
        finalCol = mix(finalCol, sprinkleCol, seedPattern * u_paper_texture * 3.0 * hole);
        finalCol *= 1.0 - (grain * u_paper_texture * 0.3);
    }

    // 7. Post Processing
    float vignette = smoothstep(1.4, 0.3, length(uv_orig));
    finalCol = mix(bgCol, finalCol, vignette); // Fade to the light blue background at edges

    // Final Toning
    finalCol = pow(finalCol, vec3(0.9)); 
    finalCol = smoothstep(-0.01, 1.01, finalCol);

    fragColor = vec4(finalCol, 1.0);
}
